mapper.update:
UPDATE processing_task
SET lease_until = DATE_ADD(UTC_TIMESTAMP(6), INTERVAL #{leaseSeconds} SECOND),
    updated_at = UTC_TIMESTAMP(6)
WHERE id = #{taskId}
  AND generation = #{generation}
  AND execution_epoch = #{executionEpoch}
  AND worker_id = #{workerId}
  AND state = 'RUNNING'
  AND lease_until > UTC_TIMESTAMP(6)

UPDATE processing_task
SET progress = LEAST(99, GREATEST(0, #{percent})),
    updated_at = UTC_TIMESTAMP(6)
WHERE id = #{taskId}
  AND generation = #{generation}
  AND execution_epoch = #{executionEpoch}
  AND worker_id = #{workerId}
  AND state = 'RUNNING'
  AND lease_until > UTC_TIMESTAMP(6)

mapper.select:
SELECT  FROM task_attempt a
WHERE a.task_id = #{taskId}
ORDER BY a.generation DESC, a.attempt DESC
LIMIT #{limit} OFFSET #{offset}
